// ===============================
// NORMALIZE & TIMESTAMP
// ===============================

function toNumber(value) {
    if (value === undefined || value === null) return null;
    const cleaned = String(value).trim();
    const num = Number(cleaned);
    return isNaN(num) ? null : num;
}

const row = msg.payload;

msg.payload = {
    metadata: {
        original_date: row.date || null,
        source: "data-acq",
    },
    sensors: {
        energy: {
            appliances: toNumber(row.Appliances),
            lights: toNumber(row.lights)
        },
        indoor: {
            T1: toNumber(row.T1),
            RH_1: toNumber(row.RH_1),
            T2: toNumber(row.T2),
            RH_2: toNumber(row.RH_2),
            T3: toNumber(row.T3),
            RH_3: toNumber(row.RH_3),
            T4: toNumber(row.T4),
            RH_4: toNumber(row.RH_4),
            T5: toNumber(row.T5),
            RH_5: toNumber(row.RH_5),
            T6: toNumber(row.T6),
            RH_6: toNumber(row.RH_6),
            T7: toNumber(row.T7),
            RH_7: toNumber(row.RH_7),
            T8: toNumber(row.T8),
            RH_8: toNumber(row.RH_8),
            T9: toNumber(row.T9),
            RH_9: toNumber(row.RH_9)
        },
        outdoor: {
            temperature: toNumber(row.T_out),
            humidity: toNumber(row.RH_out),
            pressure_mm_hg: toNumber(row.Press_mm_hg),
            windspeed: toNumber(row.Windspeed),
            visibility: toNumber(row.Visibility),
            dewpoint: toNumber(row.Tdewpoint)
        },
        randomness: {
            rv1: toNumber(row.rv1),
            rv2: toNumber(row.rv2)
        }
    }
};

return msg;

// ===============================
// BUILD TOPICS - 1 SENSOR = 1 TOPIC
// ===============================

const base = msg.payload;
const baseMetadata = base.metadata || {};

let messages = [];
let sequence = 0;

const sampleRoot = String(baseMetadata.timestamp_acq || Date.now());
const sampleId = 'sample_' + sampleRoot + '_' + Math.random().toString(16).slice(2, 10);

function buildMetadata(sensorGroup, sensorKey) {
    sequence += 1;

    return {
        ...baseMetadata,
        sample_id: sampleId,
        message_id: sampleId + '_' + sensorGroup + '_' + sensorKey + '_' + sequence,
        sensor_group: sensorGroup,
        sensor_key: sensorKey
    };
}

const roomMap = {
    1: "kitchen",
    2: "livingroom",
    3: "laundry",
    4: "office",
    5: "bathroom",
    6: "outside_building",
    7: "ironing_room",
    8: "teen_room",
    9: "parents_room"
};

for (let key in base.sensors.energy) {
    messages.push({
        topic: `data/energy/${key}`,
        payload: {
            metadata: buildMetadata("energy", key),
            value: base.sensors.energy[key]
        }
    });
}

for (let key in base.sensors.indoor) {
    const number = key.match(/[0-9]+/)[0];
    const roomName = roomMap[number] || `room_${number}`;
    const type = key.startsWith("T") ? "temperature" : "humidity";

    messages.push({
        topic: `data/home/${roomName}/${type}`,
        payload: {
            metadata: buildMetadata("indoor", key),
            value: base.sensors.indoor[key]
        }
    });
}

for (let key in base.sensors.outdoor) {
    messages.push({
        topic: `data/weather_station/${key}`,
        payload: {
            metadata: buildMetadata("outdoor", key),
            value: base.sensors.outdoor[key]
        }
    });
}

for (let key in base.sensors.randomness) {
    messages.push({
        topic: `data/random/${key}`,
        payload: {
            metadata: buildMetadata("randomness", key),
            value: base.sensors.randomness[key]
        }
    });
}

return [messages];

// ===============================
// ENCRYPT TOPIC (AES-256-CBC)
// ===============================

const algorithm = "aes-256-cbc";
const sharedSecret = env.get("TOPIC_AES_SECRET");

if (!sharedSecret || sharedSecret.length < 16) {
    node.error("TOPIC_AES_SECRET non configurato o troppo corto");
    return null;
}

const key = crypto.createHash("sha256")
                  .update(sharedSecret)
                  .digest();

const iv = crypto.randomBytes(16);
const cipher = crypto.createCipheriv(algorithm, key, iv);

let encrypted = cipher.update(String(msg.topic || ""), "utf8", "hex");
encrypted += cipher.final("hex");

msg.topic = "enc/" + iv.toString("hex") + "/" + encrypted;

return msg;

// Salva dataset completo in memoria globale
if (!Array.isArray(msg.payload) || msg.payload.length === 0) {
    global.set("dataset", null);
    global.set("index", 0);
    global.set("dataset_ready", false);
    node.error("Dataset vuoto o non valido");
    return null;
}

global.set("dataset", msg.payload);
global.set("index", 0);
global.set("dataset_ready", true);

node.warn("Dataset caricato: " + msg.payload.length + " righe");

return null;

const ready = global.get("dataset_ready");
const dataset = global.get("dataset");

if (!ready || !Array.isArray(dataset) || dataset.length === 0) {
    node.warn("Dataset non ancora caricato");
    return null;
}

let index = global.get("index") || 0;

if (index >= dataset.length) {
    index = 0; // loop infinito
}

msg.payload = dataset[index];

global.set("index", index + 1);

return msg;

// ===============================
// ENCRYPT PAYLOAD (ECC + AES)
// VERSIONE DEFINITIVA
// ===============================

const EC = elliptic.ec;
const ec = new EC('secp256k1');

const originalPayload = msg.payload || {};
const originalMetadata = originalPayload.metadata || {};

const keys = global.get("ecc_public_keys");
const keyId = global.get("current_key_id");

if (!keys || !keys[keyId]) {
    node.warn("Public key non disponibile");
    return null;
}
const publicKeyHex = keys[keyId];
const recipientPublic = ec.keyFromPublic(publicKeyHex, 'hex');

const aesKey = crypto.randomBytes(32);
const iv = crypto.randomBytes(16);

const cipher = crypto.createCipheriv('aes-256-cbc', aesKey, iv);

let encryptedData = cipher.update(JSON.stringify(originalPayload), 'utf8', 'hex');
encryptedData += cipher.final('hex');

const ephemeral = ec.genKeyPair();
const sharedSecret = ephemeral.derive(recipientPublic.getPublic());

const derivedKey = crypto.createHash('sha256')
                         .update(sharedSecret.toString(16))
                         .digest();

const cipherKey = crypto.createCipheriv('aes-256-cbc', derivedKey, iv);

let encryptedAESKey = cipherKey.update(aesKey.toString('hex'), 'utf8', 'hex');
encryptedAESKey += cipherKey.final('hex');

msg.payload = {
    metadata: {
        message_id: originalMetadata.message_id || null,
        sample_id: originalMetadata.sample_id || null,
        timestamp_acq: originalMetadata.timestamp_acq || null
    },
    key_id: keyId,
    encrypted_data: encryptedData,
    encrypted_key: encryptedAESKey,
    iv: iv.toString('hex'),
    ephemeral_pub: ephemeral.getPublic('hex')
};

return msg;

let keys = global.get("ecc_public_keys") || {};

keys[msg.payload.key_id] = msg.payload.public_key;

global.set("ecc_public_keys", keys);

// Memorizza anche quale ÃƒÆ’Ã†â€™Ãƒâ€šÃ‚Â¨ lÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬ÃƒÂ¢Ã¢â‚¬Å¾Ã‚Â¢ultima attiva
global.set("current_key_id", msg.payload.key_id);

node.warn("Nuova public key: " + msg.payload.key_id);

return null;

// ===============================
// ADD TRACE TIMESTAMP
// ===============================

const encrypted = msg.payload || {};
const metadata = encrypted.metadata || {};

msg.payload = {
    tracing: {
        data_acq_send: Date.now()
    },
    metadata: {
        message_id: metadata.message_id || null,
        sample_id: metadata.sample_id || null,
        timestamp_acq: metadata.timestamp_acq || null
    },
    encrypted: encrypted
};

return msg;
